import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百六十六章 毒箭刺穿身体","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/166第一百六十六章 毒箭刺穿身体.md","filePath":"meditation/巴利文大藏经/166第一百六十六章 毒箭刺穿身体.md"}'),r={name:"meditation/巴利文大藏经/166第一百六十六章 毒箭刺穿身体.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百六十六章-毒箭刺穿身体" tabindex="-1">第一百六十六章 毒箭刺穿身体 <a class="header-anchor" href="#第一百六十六章-毒箭刺穿身体" aria-label="Permalink to &quot;第一百六十六章 毒箭刺穿身体&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部17相应7经/涂有毒的经(利得恭敬相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望，这些是让人内心颤抖恐怖的，这些是让人内心激烈搅动的，这些是让人内心暴躁不安的，这些是修行人内心达到清净安稳的障碍，这些是修行人内心挣脱束缚捆绑的阻碍。</p><p>弟子们，谁想被毒箭刺穿身体就去贪求世间人丰厚的供养，就去贪求富贵舒适的生活，就去贪求世间人虔诚的尊敬、恭敬，就去贪求家喻户晓的名誉声望。贪求这些就如同被毒箭刺穿身体，贪求这些就无法完成各种修行，就无法证悟解脱的果位，就无法除灭一切的烦恼和痛苦，就无法从生死轮回中解脱出来，就无法证悟不生不灭的涅槃境界。</p><p>弟子们，毒箭是个比喻，毒箭指的就是世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望，一旦贪求这些就如同被毒箭刺穿身体！</p><p>弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望就是这样的让人内心颤抖恐怖，就是这样的让人内心激烈搅动，就是这样的让人内心暴躁不安。</p><p>世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望是修行人内心达到清净安稳的障碍，是修行人内心挣脱束缚捆绑的阻碍。弟子们，因此，你们应该这样去修行：「我们要舍离、放弃已经获得的丰厚供养，我们要舍离、放弃已经获得的富贵舒适的生活，我们要舍离、放弃已经获得的世间人虔诚的尊敬、恭敬，我们要舍离、放弃已经获得的家喻户晓的名誉声望。而且我们不要执着和挂念这些已经获得的丰厚供养，不要执着和挂念这些已经获得的富贵舒适的生活，不要执着和挂念这些已经获得的世间人虔诚的尊敬、恭敬，不要执着和挂念这些已经获得的家喻户晓的名誉声望。我们不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望扰乱我们的内心；不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望让我们胡思乱想、内心散乱。」弟子们，你们就应该这样的去修行。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
